-- P2 (data releases): archive root on the registry, immutability trigger,
-- new deploy_events actions (docs/design-data-releases-impl-plan.md §4).
-- Adds root / program_slug / archived_from_key / archived_at /
-- archived_by_deployment / collected_at to storage_objects (nullable or
-- defaulted: no table rewrite on 845k rows), the root and status CHECKs, three
-- partial indexes (empty: nothing is archived yet), protect_archive_rows, and
-- archive / collect / freeze / publish_dr / withdraw_dr as event actions.
-- Generated by pg-delta; header by hand; the CHECK constraints on
-- storage_objects are added NOT VALID and validated afterwards so the
-- validation scan takes SHARE UPDATE EXCLUSIVE instead of blocking the table.
-- program_slug on existing NIRSpec rows is backfilled by
-- scripts/backfill_registry_program_slug.py, not here.
SET lock_timeout = '5s';
SET statement_timeout = '60s';

SET local check_function_bodies = off;

ALTER TABLE "public"."deploy_events"
  DROP CONSTRAINT "deploy_events_action_check";

ALTER TABLE "public"."storage_objects"
  DROP CONSTRAINT "storage_objects_status_check";

ALTER TABLE "public"."storage_objects"
  ADD COLUMN "root" text NOT NULL DEFAULT 'live'::text;

ALTER TABLE "public"."storage_objects"
  ADD COLUMN "program_slug" text;

ALTER TABLE "public"."storage_objects"
  ADD COLUMN "archived_from_key" text;

ALTER TABLE "public"."storage_objects"
  ADD COLUMN "archived_at" timestamp WITH time zone;

ALTER TABLE "public"."storage_objects"
  ADD COLUMN "archived_by_deployment" integer;

ALTER TABLE "public"."storage_objects"
  ADD COLUMN "collected_at" timestamp WITH time zone;

CREATE OR REPLACE FUNCTION public.log_deploy_event (
  p_action         text,
  p_actor          uuid    DEFAULT NULL::uuid,
  p_deployment_id  integer DEFAULT NULL::integer,
  p_observation    text    DEFAULT NULL::text,
  p_field          text    DEFAULT NULL::text,
  p_affected_count integer DEFAULT NULL::integer,
  p_metadata       jsonb   DEFAULT NULL::jsonb,
  p_host           text    DEFAULT NULL::text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  AS $function$
DECLARE
  v_is_admin boolean;
  v_id uuid;
BEGIN
  SELECT COALESCE(up.is_admin, false) INTO v_is_admin
  FROM user_profiles up WHERE up.user_id = auth.uid();
  IF NOT (COALESCE(v_is_admin, false) OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'Access denied: Admin privileges required';
  END IF;

  IF p_action NOT IN ('upload', 'publish', 'revoke', 'recover', 'supersede', 'delete', 'config_sync',
                      'archive', 'collect', 'freeze', 'publish_dr', 'withdraw_dr') THEN
    RAISE EXCEPTION 'Invalid deploy_event action: %', p_action;
  END IF;

  INSERT INTO deploy_events(actor, action, deployment_id, observation, field, affected_count, metadata, host)
  VALUES (p_actor, p_action, p_deployment_id, p_observation, p_field, p_affected_count, p_metadata, p_host)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.protect_archive_rows()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.root = 'archive' THEN
      RAISE EXCEPTION 'archive registry rows are immutable: cannot delete %', OLD.storage_key
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    -- collected_at is assigned by the archived -> collected transition, never
    -- supplied: an archived row starts without one, a row inserted as
    -- collected (a backfill) is stamped now.
    IF NEW.root = 'archive' THEN
      NEW.collected_at := CASE WHEN NEW.status = 'collected' THEN now() ELSE NULL END;
    END IF;
    RETURN NEW;
  END IF;
  -- UPDATE
  IF OLD.root <> 'archive' AND NEW.root = 'archive' THEN
    RAISE EXCEPTION 'a live registry row cannot become an archive row (%); insert the archive row instead', OLD.storage_key
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.root = 'archive' THEN
    -- The whole row is frozen except the status transition, its timestamp and
    -- the bookkeeping updated_at (bumped by the generic trigger).
    IF (to_jsonb(NEW) - 'status' - 'collected_at' - 'updated_at')
       IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'collected_at' - 'updated_at')
    THEN
      RAISE EXCEPTION 'archive registry rows are immutable: % may only move archived -> collected', OLD.storage_key
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NOT (OLD.status = 'archived' AND NEW.status = 'collected') THEN
        RAISE EXCEPTION 'archive registry row % status may only move archived -> collected (got % -> %)',
          OLD.storage_key, OLD.status, NEW.status USING ERRCODE = 'integrity_constraint_violation';
      END IF;
      NEW.collected_at := now();
    ELSIF NEW.collected_at IS DISTINCT FROM OLD.collected_at THEN
      RAISE EXCEPTION 'archive registry row %: collected_at follows the status transition', OLD.storage_key
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION "public"."protect_archive_rows"() FROM PUBLIC, "anon";

ALTER TABLE "public"."deploy_events"
  ADD CONSTRAINT "deploy_events_action_check"
    CHECK
    ((action = ANY (ARRAY['upload'::text, 'publish'::text, 'revoke'::text, 'recover'::text, 'supersede'::text, 'delete'::text, 'config_sync'::text, 'archive'::text,
    'collect'::text, 'freeze'::text, 'publish_dr'::text, 'withdraw_dr'::text])));

ALTER TABLE "public"."storage_objects"
  ADD CONSTRAINT "storage_objects_root_check" CHECK ((root = ANY (ARRAY['live'::text, 'archive'::text]))) NOT VALID;
ALTER TABLE "public"."storage_objects" VALIDATE CONSTRAINT "storage_objects_root_check";

ALTER TABLE "public"."storage_objects"
  ADD CONSTRAINT "storage_objects_root_status_check"
    CHECK
    ((((root = 'live'::text) AND (status <> ALL (ARRAY['archived'::text, 'collected'::text]))) OR ((root = 'archive'::text) AND (status = ANY (ARRAY['archived'::text,
    'collected'::text])) AND (storage_key ~~ 'archive/%'::text)))) NOT VALID;
ALTER TABLE "public"."storage_objects" VALIDATE CONSTRAINT "storage_objects_root_status_check";

ALTER TABLE "public"."storage_objects"
  ADD CONSTRAINT "storage_objects_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'superseded'::text, 'revoked'::text, 'archived'::text, 'collected'::text]))) NOT VALID;
ALTER TABLE "public"."storage_objects" VALIDATE CONSTRAINT "storage_objects_status_check";

CREATE INDEX idx_storage_objects_archive_hash ON public.storage_objects USING btree (content_hash)
  WHERE (root = 'archive'::text);

CREATE INDEX idx_storage_objects_archive_program ON public.storage_objects USING btree (program_slug)
  WHERE (root = 'archive'::text);

CREATE INDEX idx_storage_objects_archive_spectrum ON public.storage_objects USING btree (spectrum_id, product_type)
  WHERE (root = 'archive'::text);

CREATE TRIGGER protect_archive_rows_trigger
  BEFORE INSERT OR DELETE OR UPDATE ON public.storage_objects
  FOR EACH ROW
  EXECUTE FUNCTION public.protect_archive_rows();

COMMENT ON COLUMN "public"."storage_objects"."archived_from_key" IS 'Archive rows: the live key whose previous bytes this object retained (retain-on-supersede); NULL for a copy made by a DR freeze.';

COMMENT ON COLUMN "public"."storage_objects"."program_slug" IS 'Row-local program scope for NIRSpec rows (copied from spectra.program_slug by deploy / the retain step / the backfill), so archive rows authorize without a live join. NULL for NIRCam products.';

COMMENT ON COLUMN "public"."storage_objects"."root" IS 'live = mutable current pointer (upserted in place); archive = write-once object under archive/<sha256>/<relpath> (data releases, P2). Archive rows are never deleted and only move archived -> collected (protect_archive_rows).';

GRANT EXECUTE ON FUNCTION "public"."protect_archive_rows"() TO "authenticated";

REVOKE ALL ON FUNCTION "public"."protect_archive_rows"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."protect_archive_rows"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."protect_archive_rows"() TO "service_role";
